# -*- coding: utf-8 -*-
from wid_h import *
W={}
W['eq']={'Undo, in reverse':dict(k='bal',hook='Solve 2x + 3 = 11 by doing the same thing to both sides.',a=2,b=3,c=11,take='Whatever you do to one side, do to the other.'),
'Variables on both sides':plot('Where do the two lines meet? That x solves the equation.',['2*x+1','m*x+7'],[P('m','Slope of second line',-2,1,1,-1)],x=(-6,6),y=(-8,12),out='The lines cross where 2x + 1 = {m}x + 7.')}
W['lin']={'Slope':plot('Slope is rise over run. Change it and watch the steepness.',['m*x'],[P('m','Slope m',-3,3,.5,1)],x=(-4,4),y=(-6,6),out='Rise {m} for every 1 across. Positive goes up, negative goes down.',pre=('Which line is steeper: slope 3 or slope 1?',['Slope 3','Slope 1'],0,'A bigger slope rises more for each step across.')),
'Slope-intercept form':plot('y = mx + b: m tilts the line, b lifts it.',['m*x+b'],[P('m','m',-3,3,.5,1),P('b','b',-5,5,1,2)],x=(-5,5),y=(-8,8),out='y = {m}x + {b}. It crosses the y-axis at <b>{b}</b>.',pts=[dict(x='0',y='b',l='b')])}
W['sys']={'What is a solution?':plot('A solution to a system is where the lines cross.',['x+1','m*x+5'],[P('m','Slope of line 2',-2,1,1,-1)],x=(-6,6),y=(-6,10),out='The solution is the crossing point.'),}
W['exp']={'Multiply, same base':calc('Same base: add the exponents.',[P('a','Exponent a',1,6,1,2),P('b','Exponent b',1,6,1,3)],[O('2ᵃ × 2ᵇ','2^(a+b)',2048,'',0)],note='2^{a} × 2^{b} = 2^({a}+{b}) = <b>{=2^(a+b)|0}</b>.')}
W['fac']={'Trinomials x² + bx + c':plot('Factors show where the parabola crosses the x-axis.',['(x-p)*(x-q)'],[P('p','p',-5,5,1,-2),P('q','q',-5,5,1,3)],x=(-7,7),y=(-8,14),out='(x − {p})(x − {q}) = x² + ({=-(p+q)|0})x + ({=p*q|0}).')}
W['rad']={'Square roots':calc('A square root finds the side of a square from its area.',[P('a','Area',1,100,1,25)],[O('Side','sqrt(a)',10,'',2)],note='√{a} = <b>{=sqrt(a)|2}</b>.')}
W['qdr']={'Quadratic shape':plot('Every parabola has the same shape; a squeezes it or flips it.',['a*x^2'],[P('a','a',-3,3,.5,1)],x=(-5,5),y=(-10,10),out='a = {a}. Positive opens up, negative opens down.'),'Vertex':plot('The vertex is the turning point.',['(x-h)^2+k'],[P('h','h',-4,4,1,1),P('k','k',-4,4,1,-2)],x=(-6,6),y=(-6,10),out='Vertex (<b>{h}</b>, <b>{k}</b>).',pts=[dict(x='h',y='k')])}
W['bas']={'Angle pairs':calc('Angles that sit on a straight line add to 180°.',[P('a','Angle a',10,170,5,60,'°')],[O('Angle b','180-a',180,'°',0)],note='a + b = 180°, so b = <b>{=180-a|0}°</b>.')}
W['par']={'Angle sum in a triangle':calc('Angles in any triangle always add to 180°.',[P('a','Angle A',10,150,5,60,'°'),P('b','Angle B',10,150,5,50,'°')],[O('Angle C','180-a-b',180,'°',0)],note='C = 180 − {a} − {b} = <b>{=180-a-b|0}°</b>.',pre=('A triangle has angles 60° and 50°. The third angle is…',['60°','70°','80°'],1,'180 − 60 − 50 = 70.')),
'Polygon angles':calc('More sides, more angle total.',[P('n','Number of sides',3,12,1,5)],[O('Angle total','(n-2)*180',1800,'°',0)],eq='sum = (n − 2) × 180°',note='A {n}-sided shape has angles totalling <b>{=(n-2)*180|0}°</b>. Each regular angle: <b>{=(n-2)*180/n|1}°</b>.')}
W['rt']={'Pythagorean theorem':calc('Legs a and b make a right triangle. Find the long side.',[P('a','Leg a',1,12,1,3),P('b','Leg b',1,12,1,4)],[O('Hypotenuse','sqrt(a^2+b^2)',17,'',2)],eq='a² + b² = c²',note='√({a}² + {b}²) = <b>{=sqrt(a^2+b^2)|2}</b>.',pre=('Legs 3 and 4. The long side is…',['5','7','6'],0,'9 + 16 = 25, and √25 = 5.')),
'Sine, cosine, tangent':simple('tri','Resize the triangle, change the angle, watch the ratios.')}
W['area']={'Triangle':calc('A triangle is half of a rectangle.',[P('b','Base',1,20,1,8),P('h','Height',1,20,1,5)],[O('Area','b*h/2',200,'',1)],eq='A = ½ b h',note='½ × {b} × {h} = <b>{=b*h/2|1}</b>.'),'Circles':calc('Circle area grows with radius squared.',[P('r','Radius',1,10,1,3)],[O('Area','pi*r^2',320,'',1)],note='π × {r}² = <b>{=pi*r^2|1}</b>.')}
W['cir']={'Inscribed angles':calc('The center angle is twice the angle on the edge.',[P('c','Central angle',20,160,10,100,'°')],[O('Inscribed angle','c/2',90,'°',0)],note='Inscribed = {c} ÷ 2 = <b>{=c/2|0}°</b>.')}
W['crd']={'Distance formula':calc('Distance is the Pythagorean theorem on the grid.',[P('dx','Across',1,12,1,3),P('dy','Up',1,12,1,4)],[O('Distance','sqrt(dx^2+dy^2)',17,'',2)],note='√({dx}² + {dy}²) = <b>{=sqrt(dx^2+dy^2)|2}</b>.')}
W['trn']={'Dilation and compositions':calc('A dilation scales every length by the same factor.',[P('k','Scale factor',.5,4,.5,2),P('s','Side',1,10,1,3)],[O('New side','k*s',40,'',1),O('New area (× k²)','k*k*s*s',160,'',1)],note='Lengths × {k}, area × {=k*k|2}.')}
W['sim']={'Perimeter and area':calc('Scale a shape by k. Perimeter scales by k, area by k².',[P('k','Scale factor',1,5,1,2)],[O('Perimeter ×','k',5,'',0),O('Area ×','k^2',25,'',0)],note='Area is <b>{=k^2|0}</b> times bigger.')}
WID=W
